pub(crate) fn integer_rank(name: &str) -> i64 {
    if name == "u8" { return 0; }
    if name == "u32" { return 1; }
    if name == "u64" { return 2; }
    if name == "i32" { return 3; }
    if name == "i64" { return 4; }
    -1
}

